def _arrow(d, p, q, size=5):
    """An arrowhead at q, pointing from p."""
    a = math.atan2(q[1] - p[1], q[0] - p[0])
    l = (q[0] - size * math.cos(a - 0.45), q[1] - size * math.sin(a - 0.45))
    r = (q[0] - size * math.cos(a + 0.45), q[1] - size * math.sin(a + 0.45))
    d.line(l, q, r)


def _box(d, x, y, w, h):
    d.line((x, y), (x + w, y), (x + w, y + h), (x, y + h), closed=True)


def _proj(w, s, e, x0=10, x1=390, y1=290):
    """An equirectangular projection true to scale at 39 N: lon w..e fills x0..x1, lat s fills y1 upward."""
    k = (x1 - x0) / (e - w)
    ky = k / math.cos(math.radians(39.0))
    return lambda p: (round(x0 + (p[0] - w) * k, 2), round(y1 - (p[1] - s) * ky, 2))


def _frame(x0=10, y0=10, x1=390, y1=290):
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1), (x0, y0)]


def _draw_lines(d, P, paths, win):
    for p in paths:
        for seg in clip([P(q) for q in p], win):
            if len(seg) > 1:
                d.line(*seg)


def aol_dulles():
    """Eastern Loudoun in plan: Route 7, the Dulles Toll Road and Greenway, Route 28, the airport, Ashburn,
    the county line, and the data center buildings standing today that the county dates to 2001 or before."""
    d = D()
    P = _proj(-77.60, 38.932, -77.36)
    win = _frame()
    d.group('thin')
    d.line(*win)
    for lon in (-77.55, -77.50, -77.45, -77.40):          # meridians as ticks
        x, _ = P((lon, 39.0))
        d.line((x, 10), (x, 16)); d.line((x, 284), (x, 290))
    for lat in (38.95, 39.0, 39.05):
        _, y = P((-77.5, lat))
        d.line((10, y), (16, y)); d.line((384, y), (390, y))
    _draw_lines(d, P, COUNTY, win)                       # the Loudoun-Fairfax line
    d.group('mid')
    for ring in (ASHBURN, STERLING):
        pts = [P(q) for q in ring]
        for seg in clip(pts + [pts[0]], win):
            d.dashed(*seg, dash=3, gap=3)
    for ring in AIRPORT:
        pts = [P(q) for q in ring]
        for seg in clip(pts + [pts[0]], win):
            d.line(*seg)
    d.group()
    _draw_lines(d, P, RT7, win)
    _draw_lines(d, P, R267, win)
    _draw_lines(d, P, RT28, win)
    d.group('mid')
    for q in DC2001:                                      # buildings standing today, built by 2001
        x, y = P(q)
        if 12 < x < 388 and 12 < y < 288:
            _box(d, x - 2.2, y - 2.2, 4.4, 4.4)
    ax, ay = P((-77.4457, 39.0052))                       # 22000 AOL Way (Census geocoder)
    d.circle(ax, ay, 6.5)
    d.line((ax - 4.6, ay + 4.6), (ax - 48, ay + 27))
    d.group('labels')
    d.text(ax - 52, ay + 30, 'AOL, 1996', size=7, anchor='end')
    d.text(300, 58, 'ROUTE 7', size=7, anchor='start')
    d.text(40, 110, 'DULLES GREENWAY', size=7, anchor='start')
    d.text(345, 230, 'TOLL ROAD', size=7)
    x, y = P((-77.487, 38.940)); d.text(x, y, 'AIRPORT', size=7)
    x, y = P((-77.476, 39.036)); d.text(x, y, 'ASHBURN', size=7)
    d.text(335, 150, 'STERLING', size=7)
    d.text(296, 180, 'RT 28', size=7, anchor='start')
    d.text(250, 282, 'LOUDOUN', size=7, anchor='end')
    d.text(300, 282, 'FAIRFAX', size=7, anchor='start')
    d.text(20, 280, 'SQUARES: BUILT BY 2001', size=7, anchor='start')
    return d


def data_center_alley():
    """The same roads, closer in, with every data center building the county counted on September 1, 2026:
    a circle for each, its area in proportion to the building's floor area; built solid, under construction
    dashed."""
    d = D()
    P = _proj(-77.545, 38.958, -77.395)
    win = _frame()
    d.group('thin')
    d.line(*win)
    for lon in (-77.52, -77.48, -77.44, -77.40):
        x, _ = P((lon, 39.0))
        d.line((x, 10), (x, 16)); d.line((x, 284), (x, 290))
    for lat in (38.98, 39.02, 39.06):
        _, y = P((-77.5, lat))
        d.line((10, y), (16, y)); d.line((384, y), (390, y))
    _draw_lines(d, P, COUNTY, win)
    for ring in AIRPORT:
        pts = [P(q) for q in ring]
        for seg in clip(pts + [pts[0]], win):
            d.dashed(*seg, dash=3, gap=3)
    d.group()
    _draw_lines(d, P, RT7, win)
    _draw_lines(d, P, R267, win)
    _draw_lines(d, P, RT28, win)
    d.group('mid')
    for lon, lat, ksf, built in sorted(DCALL, key=lambda b: -b[2]):
        x, y = P((lon, lat))
        r = max(1.5, 0.3 * math.sqrt(max(ksf, 1)))      # area in proportion to floor area
        if 10 + r < x < 390 - r and 10 + r < y < 290 - r:
            if built:
                d.circle(x, y, r)
            else:
                d.arc(x, y, r, 0, 300)
    d.group('labels')
    d.text(385, 95, 'ROUTE 7', size=7, anchor='end')
    d.text(20, 118, 'DULLES GREENWAY', size=7, anchor='start')
    x, y = P((-77.460, 38.963)); d.text(x, y, 'AIRPORT', size=7)
    d.text(292, 40, 'RT 28', size=7, anchor='end')
    d.text(34, 172, '100,000 SQ FT', size=7, anchor='start')
    d.text(20, 186, 'OPEN: UNDER CONSTRUCTION', size=7, anchor='start')
    d.circle(25, 169.5, 0.3 * math.sqrt(100))
    return d


def loudoun_revenue():
    """Loudoun's assessment of a server, as a share of its cost, year by year: the schedule in force from
    2026 (60, 45, 30, 15, 10, then 5 per cent) solid, the one before it (50, 40, 30, 20, then 10) dashed,
    and the equipment replaced after five years, which starts the schedule again."""
    d = D()
    x0, x1, y0, y1 = 52, 380, 62, 252          # plot box: years 0..15 across, 0..70 per cent up
    yr = lambda t: x0 + (x1 - x0) * t / 15
    pc = lambda v: y1 - (y1 - y0) * v / 70
    new = [60, 45, 30, 15, 10]
    old = [50, 40, 30, 20, 10]
    d.group('thin')
    d.line((x0, y0), (x0, y1), (x1, y1))
    for v in (10, 20, 30, 40, 50, 60):
        d.line((x0 - 4, pc(v)), (x1, pc(v)))
    for t in range(16):
        d.line((yr(t), y1), (yr(t), y1 + 4))
    for t in (5, 10):                                       # refresh lines
        d.line((yr(t), y0 - 6), (yr(t), y1))
    d.group()
    pts = []
    for cycle in range(3):
        for i, v in enumerate(new):
            t = cycle * 5 + i
            pts += [(yr(t), pc(v)), (yr(t + 1), pc(v))]
    d.line(*pts)
    d.group('mid')
    pts = []
    for cycle in range(3):
        for i, v in enumerate(old):
            t = cycle * 5 + i
            pts += [(yr(t), pc(v)), (yr(t + 1), pc(v))]
    d.dashed(*pts, dash=4, gap=3)
    for t in (5, 10):
        _arrow(d, (yr(t), pc(10) - 2), (yr(t), pc(60) + 3), 4)
    d.group('labels')
    for v in (20, 40, 60):
        d.text(x0 - 8, pc(v) + 2.5, f'{v}%', size=7, anchor='end')
    for t in (0, 5, 10, 15):
        d.text(yr(t), y1 + 14, f'{t}', size=7)
    d.text((x0 + x1) / 2, y1 + 28, 'YEARS IN SERVICE', size=7)
    d.text(x0, 20, 'ASSESSED SHARE OF ORIGINAL COST', size=7, anchor='start')
    d.text(x0, 34, 'SOLID: FROM 2026 · DASHED: BEFORE', size=7, anchor='start')
    d.text(yr(5), y0 - 10, 'REPLACED', size=7)
    d.text(yr(10), y0 - 10, 'REPLACED', size=7)
    return d


PLATES = {'aol-dulles': aol_dulles, 'data-center-alley': data_center_alley, 'loudoun-revenue': loudoun_revenue}
